<template>
  <view class="page execute-page">
    <view class="card">
      <view class="strong">巡检信息</view>
      <input v-model.trim="inspectionItem" placeholder="巡检项目（必填）" />
      <input v-model.trim="checkPosition" placeholder="巡检位置（必填）" />
      <input v-model.trim="inspectionType" placeholder="巡检类型（必填）" />
    </view>
    <view class="check-card card"><view class="row between"><view><view class="strong">现场位置打卡</view><view class="muted location-text">{{ locationText }}</view></view><view class="locate" :class="{checked:Boolean(draft.checkedAt)}" @click="checkIn">{{ draft.checkedAt?'✓':'⌖' }}</view></view></view>
    <view class="section-title">巡检结论</view><view class="result-options"><view :class="{active:draft.result==='NORMAL'}" @click="setResult('NORMAL')"><text>✓</text><view><view class="strong">正常</view><view class="muted">未发现异常</view></view></view><view class="abnormal" :class="{active:draft.result==='ABNORMAL'}" @click="setResult('ABNORMAL')"><text>!</text><view><view class="strong">异常</view><view class="muted">发现安全隐患</view></view></view></view>
    <view class="section-title">现场照片</view><view class="photo-grid"><view v-for="(photo,index) in draft.photos" :key="photo" class="photo"><image :src="photo" mode="aspectFill"/><view class="remove" @click="removePhoto(index)">×</view></view><view class="add-photo" @click="choosePhoto"><view>＋</view><text>拍照/选择</text></view></view>
    <view class="section-title">巡检说明</view><view class="card textarea-card"><textarea v-model="draft.remark" maxlength="500" placeholder="请记录设备状况、异常现象和处理建议" @input="saveDraft"/><view class="muted word-count">{{ draft.remark.length }}/500</view></view>
    <view class="actions"><button class="btn-ghost" @click="saveOnly">保存草稿</button><button class="btn-primary" :loading="submitting" @click="submit">提交巡检</button></view>
  </view>
</template>
<script setup lang="ts">
import { reactive,ref } from 'vue';import { onLoad } from '@dcloudio/uni-app';import { useAuthStore } from '@/stores/auth';import { useInspectionDraftStore,type InspectionDraft } from '@/stores/inspectionDraft';import { saveInspection, updateInspection, getInspection } from '@/api/inspection'
const auth=useAuthStore(),draftStore=useInspectionDraftStore(),taskId=ref(''),submitting=ref(false),locationText=ref('尚未打卡'),draft=reactive<InspectionDraft>({taskId:'',result:'',remark:'',photos:[]})
const inspectionItem=ref(''),checkPosition=ref(''),inspectionType=ref('日常巡检')
function saveDraft(){draftStore.save({...draft})}function setResult(v:'NORMAL'|'ABNORMAL'){draft.result=v;saveDraft()}function checkIn(){uni.getLocation({type:'gcj02',success:r=>{draft.longitude=r.longitude;draft.latitude=r.latitude;draft.checkedAt=new Date().toISOString();locationText.value=`已定位 ${r.latitude.toFixed(5)}, ${r.longitude.toFixed(5)}`;saveDraft()},fail:()=>uni.showToast({title:'定位失败，请检查位置权限',icon:'none'})})}
function choosePhoto(){if(draft.photos.length>=6){uni.showToast({title:'最多选择6张照片',icon:'none'});return}uni.chooseImage({count:Math.max(1,6-draft.photos.length),sourceType:['camera','album'],success:r=>{draft.photos.push(...r.tempFilePaths);saveDraft()}})}function removePhoto(i:number){draft.photos.splice(i,1);saveDraft()}function saveOnly(){saveDraft();uni.showToast({title:'草稿已保存',icon:'success'})}
async function submit(){if(submitting.value)return;if(!draft.checkedAt){uni.showToast({title:'请先完成位置打卡',icon:'none'});return}if(!draft.result){uni.showToast({title:'请选择巡检结论',icon:'none'});return}if(draft.result==='ABNORMAL'&&!draft.remark.trim()){uni.showToast({title:'异常巡检必须填写说明',icon:'none'});return}submitting.value=true;try{await (taskId.value ? updateInspection : saveInspection)({id:taskId.value,...draft,inspectionItem:inspectionItem.value,checkPosition:checkPosition.value,inspectionType:inspectionType.value,inspector:auth.displayName,attachmentLocalPaths:draft.photos});draftStore.remove(taskId.value);uni.showToast({title:'巡检提交成功',icon:'success'});setTimeout(()=>uni.switchTab({url:'/pages/inspection/index'}),500)}catch(e){uni.showToast({title:e instanceof Error?e.message:'提交失败，草稿已保留',icon:'none'})}finally{submitting.value=false}}
onLoad(async o=>{taskId.value=String(o?.id||'');Object.assign(draft,draftStore.get(taskId.value));draft.taskId=taskId.value;if(draft.checkedAt)locationText.value='已完成现场定位';if(taskId.value){try{const item=await getInspection(taskId.value);inspectionItem.value=item.title||'';checkPosition.value=item.location||'';inspectionType.value=String(item.inspectionType||'日常巡检')}catch{uni.showToast({title:'巡检信息加载失败，请返回重试',icon:'none'})}}})
</script>
<style scoped>.check-card{border:2rpx solid #d8ebe7}.location-text{font-size:21rpx;margin-top:9rpx}.locate{width:82rpx;height:82rpx;display:grid;place-items:center;border-radius:50%;font-size:34rpx;color:#087f72;background:#e7f6f3}.locate.checked{color:#fff;background:#087f72}.result-options{display:grid;grid-template-columns:1fr 1fr;gap:16rpx}.result-options>view{display:flex;align-items:center;gap:18rpx;padding:24rpx;border:2rpx solid transparent;border-radius:22rpx;background:#fff}.result-options>view>text{width:54rpx;height:54rpx;display:grid;place-items:center;border-radius:16rpx;color:#087f72;background:#e7f6f3}.result-options .active{border-color:#087f72;background:#f1fbf8}.result-options .abnormal>text{color:#c56d16;background:#fff0dc}.result-options .abnormal.active{border-color:#d17a21;background:#fffaf3}.result-options .muted{font-size:20rpx;margin-top:5rpx}.photo-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14rpx}.photo,.add-photo{position:relative;height:190rpx;border-radius:18rpx;overflow:hidden}.photo image{width:100%;height:100%}.remove{position:absolute;right:8rpx;top:8rpx;width:38rpx;height:38rpx;line-height:35rpx;text-align:center;border-radius:50%;color:#fff;background:rgba(0,0,0,.55)}.add-photo{display:grid;place-content:center;text-align:center;color:#71807e;border:2rpx dashed #b8cfca;background:#f8fbfa}.add-photo view{font-size:50rpx;line-height:1}.add-photo text{font-size:20rpx;margin-top:8rpx}.textarea-card textarea{width:100%;height:220rpx;font-size:25rpx}.word-count{text-align:right;font-size:20rpx}.actions{display:grid;grid-template-columns:1fr 1.6fr;gap:16rpx;margin-top:30rpx;padding-bottom:25rpx}</style>
